void ObbMounterInstanceProxy::Init(
    ::mojo::PendingRemote<ObbMounterHost> in_host_remote, InitCallback callback) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send arc::mojom::ObbMounterInstance::Init", "input_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("host_remote"), in_host_remote,
                        "<value of type ::mojo::PendingRemote<ObbMounterHost>>");
   });
#endif

  const bool kExpectsResponse = true;
  const bool kIsSync = false;
  const bool kAllowInterrupt = true;
  const bool is_urgent = false;
  
  const uint32_t kFlags =
      ((kExpectsResponse) ? mojo::Message::kFlagExpectsResponse : 0) |
      ((kIsSync) ? mojo::Message::kFlagIsSync : 0) |
      ((kAllowInterrupt) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((is_urgent) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kObbMounterInstance_Init_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::arc::mojom::internal::ObbMounterInstance_Init_Params_Data> params(
          message);
  params.Allocate();
  mojo::internal::Serialize<mojo::InterfacePtrDataView<::arc::mojom::ObbMounterHostInterfaceBase>>(
      in_host_remote, &params->host_remote, &params.message());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      !mojo::internal::IsHandleOrInterfaceValid(params->host_remote),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_INVALID_HANDLE,
      "invalid host_remote in ObbMounterInstance.Init request");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(ObbMounterInstance::Name_);
  message.set_method_name("Init");
#endif
  std::unique_ptr<mojo::MessageReceiver> responder(
      new ObbMounterInstance_Init_ForwardToCallback(
          std::move(callback)));
  ::mojo::internal::SendMojoMessage(*receiver_, message, std::move(responder));
}
class ObbMounterInstance_Init_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static ObbMounterInstance::InitCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
    std::unique_ptr<ObbMounterInstance_Init_ProxyToResponder> proxy(
        new ObbMounterInstance_Init_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&ObbMounterInstance_Init_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~ObbMounterInstance_Init_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  ObbMounterInstance_Init_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "ObbMounterInstance::InitCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      );
};

bool ObbMounterInstance_Init_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::ObbMounterInstance_Init_ResponseParams_Data* params =
      reinterpret_cast<
          internal::ObbMounterInstance_Init_ResponseParams_Data*>(
              message->mutable_payload());
  
  
  // Validation for ObbMounterInstance.1
  bool success = true;
  ObbMounterInstance_Init_ResponseParamsDataView input_data_view(params, message);
  
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        ObbMounterInstance::Name_, 1, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run();
  return true;
}

void ObbMounterInstance_Init_ProxyToResponder::Run(
    ) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT0("mojom", "Send reply arc::mojom::ObbMounterInstance::Init");
#endif
  
  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kObbMounterInstance_Init_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::arc::mojom::internal::ObbMounterInstance_Init_ResponseParams_Data> params(
          message);
  params.Allocate();

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(ObbMounterInstance::Name_);
  message.set_method_name("Init");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

