// static
bool ObbMounterInstanceStubDispatch::AcceptWithResponder(
    ObbMounterInstance* impl,
    mojo::Message* message,
    std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
  [[maybe_unused]] const bool message_is_sync =
      message->has_flag(mojo::Message::kFlagIsSync);
  [[maybe_unused]] const uint64_t request_id = message->request_id();
  switch (message->header()->name) {
    case internal::kObbMounterInstance_Init_Name: {

      internal::ObbMounterInstance_Init_Params_Data* params =
          reinterpret_cast<
              internal::ObbMounterInstance_Init_Params_Data*>(
                  message->mutable_payload());
      
      
      // Validation for ObbMounterInstance.1
      bool success = true;
      ::mojo::PendingRemote<ObbMounterHost> p_host_remote{};
      ObbMounterInstance_Init_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_host_remote =
            input_data_view.TakeHostRemote<decltype(p_host_remote)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            ObbMounterInstance::Name_, 1, false);
        return false;
      }
      ObbMounterInstance::InitCallback callback =
          ObbMounterInstance_Init_ProxyToResponder::CreateCallback(
              *message, std::move(responder));
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Init(        
        std::move(p_host_remote), std::move(callback));
      return true;
    }
  }
  return false;
}
