void ObbMounterHostAsyncWaiter::MountObb(
    const std::string& obb_file, const std::string& target_path, int32_t owner_gid, bool* out_success) {
  base::RunLoop loop;
  proxy_->MountObb(std::move(obb_file),std::move(target_path),std::move(owner_gid),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool ObbMounterHostAsyncWaiter::MountObb(
    const std::string& obb_file, const std::string& target_path, int32_t owner_gid) {
  bool async_wait_result;
  MountObb(std::move(obb_file),std::move(target_path),std::move(owner_gid),&async_wait_result);
  return async_wait_result;
}

void ObbMounterHostAsyncWaiter::UnmountObb(
    const std::string& target_path, bool* out_success) {
  base::RunLoop loop;
  proxy_->UnmountObb(std::move(target_path),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

